	/** Where this obj sits in the arrays above, or -1 for an obj that is not a clue. */
	public static int indexOf(int objId) {
		int low = 0;
		int high = ID.length - 1;
		while (low <= high) {
			int mid = (low + high) >>> 1;
			if (ID[mid] == objId) {
				return mid;
			}
			if (ID[mid] < objId) {
				low = mid + 1;
			} else {
				high = mid - 1;
			}
		}
		return -1;
	}

	/** How many steps this table knows. */
	public static int count() {
		return ID.length;
	}
